// Ensure catalogs stay in lockstep — warn only (never throw): a hard throw here
// white-screens the whole renderer on HMR when en lags zh-CN by one key.
const missing = (Object.keys(zhCN) as MessageKey[]).filter((k) => !(k in en))
if (missing.length) {
  console.error(`i18n: en missing keys: ${missing.join(', ')}`)
  // Fill gaps so runtime t() never hits undefined for typed keys.
  for (const k of missing) {
    ;(en as Record<string, string>)[k] = zhCN[k]
  }
}
